static uint32_t CRC32(NSData *d){uint32_t c=0xffffffffU;const uint8_t *p=d.bytes;for(NSUInteger i=0;i<d.length;i++){c^=p[i];for(int j=0;j<8;j++)c=(c>>1)^((c&1)?0xedb88320U:0);}return c^0xffffffffU;}
static void U16(NSMutableData *d,uint16_t x){uint8_t b[2]={x&255,x>>8};[d appendBytes:b length:2];} static void U32(NSMutableData *d,uint32_t x){uint8_t b[4]={x&255,(x>>8)&255,(x>>16)&255,x>>24};[d appendBytes:b length:4];}
BOOL KARPAWriteZIPForDirectory(NSString *dir,NSString *out,NSError **e){if(![dir isKindOfClass:NSString.class]||![out isKindOfClass:NSString.class]){if(e)*e=[NSError errorWithDomain:@"com.example.authorized.KARPA" code:30 userInfo:@{NSLocalizedDescriptionKey:@"Invalid ZIP path"}];return NO;}NSArray *files=[[NSFileManager defaultManager] contentsOfDirectoryAtPath:dir error:e];if(!files)return NO;NSMutableData *zip=[NSMutableData data];NSMutableArray *central=[NSMutableArray array];for(NSString *name in files){if([name isEqualToString:[out lastPathComponent]])continue;NSString *path=[dir stringByAppendingPathComponent:name];BOOL isDir=NO;if(![[NSFileManager defaultManager] fileExistsAtPath:path isDirectory:&isDir]||isDir)continue;NSData *data=[NSData dataWithContentsOfFile:path options:0 error:e];if(!data)return NO;NSData *nb=[name dataUsingEncoding:NSUTF8StringEncoding];uint32_t offset=(uint32_t)zip.length,crc=CRC32(data);U32(zip,0x04034b50);U16(zip,20);U16(zip,0);U16(zip,0);U16(zip,0);U16(zip,0);U32(zip,crc);U32(zip,(uint32_t)data.length);U32(zip,(uint32_t)data.length);U16(zip,(uint16_t)nb.length);U16(zip,0);[zip appendData:nb];[zip appendData:data];[central addObject:@{ @"name":nb,@"crc":@(crc),@"size":@(data.length),@"offset":@(offset)}];}uint32_t centralOffset=(uint32_t)zip.length;for(NSDictionary *x in central){NSData *nb=x[@"name"];U32(zip,0x02014b50);U16(zip,20);U16(zip,20);U16(zip,0);U16(zip,0);U16(zip,0);U16(zip,0);U32(zip,[x[@"crc"] unsignedIntValue]);U32(zip,[x[@"size"] unsignedIntValue]);U32(zip,[x[@"size"] unsignedIntValue]);U16(zip,(uint16_t)nb.length);U16(zip,0);U16(zip,0);U16(zip,0);U16(zip,0);U32(zip,0);U32(zip,[x[@"offset"] unsignedIntValue]);[zip appendData:nb];}uint32_t centralSize=(uint32_t)zip.length-centralOffset;U32(zip,0x06054b50);U16(zip,0);U16(zip,0);U16(zip,(uint16_t)central.count);U16(zip,(uint16_t)central.count);U32(zip,centralSize);U32(zip,centralOffset);U16(zip,0);return [zip writeToFile:out options:NSDataWritingAtomic error:e];}
